// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function testFuzz_property(uint256 initialValue) public {
        // Keep initialValue small but nonzero and not too large, so getTokens still distributes
        // a positive amount and the accounting difference is visible.
        initialValue = bound(initialValue, 1, c.value());

        // The public value getter cannot be set directly; use getTokens once to set a known
        // starting point, then measure the next distribution separately.
        // First, transition through the public entry so that value() becomes the bounded amount.
        // We cannot force arbitrary value, but the fuzzer can search over msg.value amounts
        // and over the value state produced by repeated calls.
        uint256 beforeTD = c.totalDistributed();

        // Make c receive exactly enough ether; getTokens is payable and ignores msg.value.
        vm.deal(address(this), 1 ether);
        c.getTokens{value: 1 wei}();

        uint256 afterTD = c.totalDistributed();

        // General rule: totalDistributed must not decrease across getTokens.
        // The reference adds the distributed amount, so afterTD >= beforeTD always.
        // The mutant subtracts, so for a nonzero distributed amount afterTD < beforeTD.
        assertTrue(afterTD >= beforeTD);
    }
}
